strict.source:
aeon:mode = "strict"

contact:object = {
  name:string = "Bob"
  active:boolean = true
}

measurements:list<number> = [3, 4, 5]

temporal.source:
//# AEON Core preserves temporal syntax and authored precision.
//# It does not resolve timezone rules, places, leap seconds, or timescales.
//# This playground does not apply the GP schema; use the AEOS Playground for policy validation.
fractional:datetime = 2027-01-31T23:59:59.3400
leapClaim:datetime = 2016-12-31T23:59:60.5Z
unknownOffset:datetime = 2027-01-31T23:59:59-00:00

melbourneWallTime:wtc = 2027-01-31T23:59:59&Australia/Melbourne
melbourneInstant:wtc = 2027-01-31T23:59:59+11:00&Australia/Melbourne
utcAnchoredMelbourne:wtc = 2027-01-31T23:59:59Z&Australia/Melbourne
namedPlace:wtc = 2026-01-01T09:10:00+01:00&+/Antarctica/Elisabeth
localClock:wtc = 2027-01-31T23:59:59&local

//# Untyped WTC syntax is inferred as wtc rather than datetime.
atomicTime = 2026-01-01T09:10:10&TAI

